def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    V = set('aeiou')
    last = -1
    for i in range(n):
        if s[i] not in V:
            last = i
    nxt = [-1] * (n + 1)
    cur = -1
    for i in range(n - 1, -1, -1):
        nxt[i] = cur
        if s[i] not in V:
            cur = i
    small = None
    large = None
    for i in range(n):
        if s[i] in V and nxt[i] != -1:
            a = s[i:nxt[i] + 1]
            if small is None or a < small:
                small = a
            b = s[i:last + 1]
            if large is None or b > large:
                large = b
    if small is None:
        print(-1)
    else:
        print(small)
        print(large)

